// --- src/client/api.js ---
async function fetchWithTimeout(url, opts = {}, ms = 30000) {
  const controller = new AbortController()
  const timer = setTimeout(() => {
    controller.abort()
  }, ms)
  const signal = opts.signal || controller.signal
  try {
    const res = await fetch(url, { ...opts, signal })
    return res
  } catch (err) {
    if (err && (err.name === 'AbortError' || controller.signal.aborted)) {
      const sec = Math.round(ms / 1000)
      const tFn = typeof opts.t === 'function' ? opts.t : null
      const msg = tFn ? tFn('api.timeout', { seconds: sec }) : ('Request timed out (' + sec + 's)')
      throw new Error(msg)
    }
    throw err
  } finally {
    clearTimeout(timer)
  }
}

// --- src/client/settings-draft.js ---
/**
 * Staged configuration draft for the ClineBot settings page.
 *
 * Fields edited in the form are merged into `pending` and written with one
 * `PUT /config` when the user presses Save. Account operations remain
 * immediate and are handled by the page's existing handlers.
 */
function useStagedConfig({ status, draft, setDraft, load, t, pendingRef }) {
  const [pending, setPending] = React.useState({})
  const [saving, setSaving] = React.useState(false)
  const [saveState, setSaveState] = React.useState('idle')
  const [saveError, setSaveError] = React.useState('')
  const savedTimer = React.useRef(null)

  React.useEffect(() => () => {
    if (savedTimer.current) clearTimeout(savedTimer.current)
  }, [])

  const validationError = React.useMemo(() => {
    if (Object.hasOwn(pending, 'baseUrl')) {
      const raw = String(pending.baseUrl || '').trim()
      try {
        const url = new URL(raw)
        const local = url.hostname === 'localhost' || url.hostname === '127.0.0.1'
        if (url.protocol !== 'https:' && !local) return t('settings.save_invalid_base_url')
      } catch {
        return t('settings.save_invalid_base_url')
      }
    }
    for (const key of ['timeoutMs', 'smokeTimeoutMs', 'streamIdleTimeoutMs', 'maxPayloadMb']) {
      if (!Object.hasOwn(pending, key)) continue
      const value = Number(pending[key])
      if (!Number.isFinite(value) || value <= 0) return t('settings.save_invalid_number')
    }
    return ''
  }, [pending, t])

  const stage = React.useCallback((patch) => {
    if (!patch || typeof patch !== 'object') return
    const next = { ...(pendingRef.current || {}), ...patch }
    pendingRef.current = next
    setPending(next)
    setDraft((current) => ({ ...(current || {}), ...patch }))
    setSaveState('unsaved')
    setSaveError('')
  }, [pendingRef, setDraft])

  const discard = React.useCallback(() => {
    pendingRef.current = {}
    setPending({})
    setDraft(status?.config || {})
    setSaveState('idle')
    setSaveError('')
  }, [pendingRef, setDraft, status])

  const save = React.useCallback(async () => {
    const patch = pendingRef.current || {}
    if (Object.keys(patch).length === 0 || saving) return
    if (validationError) {
      setSaveState('error')
      setSaveError(validationError)
      return
    }
    setSaving(true)
    setSaveState('saving')
    setSaveError('')
    try {
      const res = await fetchWithTimeout(`${ROUTE_PREFIX}/config`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ config: patch }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok || data.ok === false) throw new Error(data.error || `HTTP ${res.status}`)
      pendingRef.current = {}
      setPending({})
      await load()
      setSaveState('saved')
      if (savedTimer.current) clearTimeout(savedTimer.current)
      savedTimer.current = setTimeout(() => {
        setSaveState((current) => (current === 'saved' ? 'idle' : current))
      }, 2500)
    } catch (error) {
      setSaveState('error')
      setSaveError(String(error?.message || error))
    } finally {
      setSaving(false)
    }
  }, [load, pendingRef, saving, validationError])

  return {
    pending,
    pendingCount: Object.keys(pending).length,
    saving,
    saveState,
    saveError,
    validationError,
    invalid: Boolean(validationError),
    stage,
    discard,
    save,
  }
}

// --- src/client/settings-models.js ---
/**
 * Model-picker selection state and debounced persistence.
 *
 * Model toggles are immediate by design: the picker is a direct inventory
 * control, not part of the staged settings form.
 */
function useModelSelection({ status, draft, setDraft, load, setErr }) {
  const debounceTimerRef = React.useRef(null)

  React.useEffect(() => () => {
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current)
  }, [])

  function debounceSaveDisabledModels(nextDisabled, previousDisabled) {
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current)
    debounceTimerRef.current = setTimeout(async () => {
      try {
        const res = await fetchWithTimeout(`${ROUTE_PREFIX}/models/toggle`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ disabledModels: nextDisabled }),
        })
        const data = await res.json().catch(() => ({}))
        if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`)
        await load()
      } catch (error) {
        console.warn('[dsh-clinebot] Failed saving disabled models:', error)
        setErr(String(error?.message || error))
        setDraft((previous) => {
          if (!previous) return previous
          const all = status?.availableModels || []
          const previousEnabled = all.map((model) => model.id).filter((id) => !previousDisabled.includes(id))
          return { ...previous, disabledModels: previousDisabled, enabledModels: previousEnabled }
        })
      }
    }, 400)
  }

  function handleToggleModel(id) {
    const current = draft?.disabledModels || []
    const next = current.includes(id)
      ? current.filter((entry) => entry !== id)
      : [...current, id]
    const all = status?.availableModels || []
    const enabled = all.map((model) => model.id).filter((modelId) => !next.includes(modelId))
    setDraft({ ...(draft || {}), disabledModels: next, enabledModels: enabled })
    debounceSaveDisabledModels(next, current)
  }

  function handleSetModelsFilter(type) {
    const all = status?.availableModels || []
    let allowed = new Set()
    if (type === 'all') allowed = new Set(all.map((model) => model.id))
    else if (type === 'vision') allowed = new Set(all.filter((model) => model.input?.includes('image') || model.input?.includes('vision')).map((model) => model.id))
    else if (type === 'coding') allowed = new Set(all.filter((model) => model.category === 'coding').map((model) => model.id))
    else if (type === 'recommended') allowed = new Set(all.filter((model) => model.recommended).map((model) => model.id))

    const current = draft?.disabledModels || []
    const nextDisabled = all.map((model) => model.id).filter((id) => !allowed.has(id))
    const nextEnabled = Array.from(allowed)
    setDraft({ ...(draft || {}), disabledModels: nextDisabled, enabledModels: nextEnabled })
    debounceSaveDisabledModels(nextDisabled, current)
  }

  return { handleToggleModel, handleSetModelsFilter }
}

