/**
 * Immediate account-pool operations. These are intentionally outside the
 * staged settings form: adding, pinning, renaming, clearing and deleting an
 * account commit on their own.
 */
function createAccountActions({ performAction, load, t, setMsg }) {
  async function handlePinAccount(accountEnv) {
    await performAction('pin-account', async () => {
      const res = await fetchWithTimeout(`${ROUTE_PREFIX}/accounts/active`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ account: accountEnv }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`)
      await load()
    })
  }

  async function handleAddAccount({ label, apiKeyEnv, apiKey, id }) {
    await performAction('add-account', async () => {
      const endpoint = id ? `${ROUTE_PREFIX}/keys/discovered/import` : `${ROUTE_PREFIX}/accounts`
      const payload = id ? { id, label, apiKeyEnv } : { label, apiKeyEnv, apiKey }
      const res = await fetchWithTimeout(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`)
      setMsg(t('key.saved_msg', { status: data.validated ? 'OK' : (data.validationError || 'Notice') }))
      await load()
    })
  }

  async function handleDeleteAccount(accountEnv, deleteSecret = true) {
    await performAction('delete-account', async () => {
      const res = await fetchWithTimeout(`${ROUTE_PREFIX}/accounts/delete`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKeyEnv: accountEnv, deleteSecret }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`)
      await load()
    })
  }

  async function handleRenameAccount(accountEnv, label) {
    await performAction('rename-account', async () => {
      const res = await fetchWithTimeout(`${ROUTE_PREFIX}/accounts/rename`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKeyEnv: accountEnv, label }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`)
      await load()
    })
  }

  async function handleClearKey(accountEnv) {
    await performAction('clear-key', async () => {
      const res = await fetchWithTimeout(`${ROUTE_PREFIX}/accounts/key/clear`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKeyEnv: accountEnv }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`)
      await load()
    })
  }

  return { handlePinAccount, handleAddAccount, handleDeleteAccount, handleRenameAccount, handleClearKey }
}

// --- src/client/error-boundary.js ---
function createErrorBoundary() {
  try {
    if (!React || typeof React.Component !== 'function') {
      return function NoopBoundary(props) { return props?.children || null }
    }
    return class ClientErrorBoundary extends React.Component {
      constructor(props) {
        super(props)
        this.state = { hasError: false, error: null }
      }
      static getDerivedStateFromError(error) {
        return { hasError: true, error }
      }
      componentDidCatch(error, info) {
        console.warn('[dsh-clinebot] Client render error caught by boundary:', error, info)
      }
      render() {
        if (this.state.hasError) {
          const t = this.props && typeof this.props.t === 'function' ? this.props.t : null
          const errorTitle = t ? t('ui.error_title') : 'ClineBot UI Error: '
          const retryLabel = t ? t('ui.retry') : 'Retry'
          return React.createElement(
            'div',
            { className: 'cb-alert-err' },
            React.createElement('strong', null, errorTitle),
            String(this.state.error?.message || this.state.error || 'Unknown rendering error'),
            React.createElement(
              'button',
              {
                type: 'button',
                className: 'cb-btn',
                style: { marginLeft: '12px', padding: '2px 8px', fontSize: '11px' },
                onClick: () => this.setState({ hasError: false, error: null }),
              },
              retryLabel
            )
          )
        }
        return this.props.children
      }
    }
  } catch (e) {
    return function FallbackBoundary(props) { return props?.children || null }
  }
}
const ErrorBoundary = createErrorBoundary()

// --- src/client/progress-bar.js ---
function formatResetCountdown(isoString) {
  if (!isoString) return ''
  try {
    const d = new Date(isoString)
    const diff = d.getTime() - Date.now()
    if (Number.isNaN(diff)) return ''
    if (diff <= 0) return 'resetting'
    const totalHours = Math.floor(diff / (1000 * 60 * 60))
    const days = Math.floor(totalHours / 24)
    const hours = totalHours % 24
    if (days > 0) {
      return `${days}d ${hours}h`
    }
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))
    if (hours > 0) {
      return `${hours}h ${minutes}m`
    }
    return `${Math.max(1, minutes)}m`
  } catch {
    return ''
  }
}

function formatResetTime(isoString) {
  if (!isoString) return ''
  try {
    const d = new Date(isoString)
    if (Number.isNaN(d.getTime())) return ''
    return d.toLocaleTimeString()
  } catch {
    return ''
  }
}

function ProgressBar({ label, percentUsed, remainingPercent, resetsAt, t }) {
  const pct = Math.max(0, Math.min(100, Math.round(percentUsed || 0)))
  const isWarn = pct >= 80 && pct < 90
  const isBad = pct >= 90
  const barClass = isBad ? 'cb-progress-bar-bad' : isWarn ? 'cb-progress-bar-warn' : 'cb-progress-bar-fill'
  const resetCountdown = formatResetCountdown(resetsAt)
  const resetClock = formatResetTime(resetsAt)

  return React.createElement(
    'div',
    {
      className: 'cb-progress-card cb-bar-container',
      style: {
        display: 'flex',
        flexDirection: 'column',
        gap: '8px',
        padding: '12px 14px',
        borderRadius: '8px',
        border: isBad ? '1px solid var(--dsw-alias-state-error-primary)' : '1px solid var(--dsw-alias-border-l2)',
        background: 'var(--dsw-alias-bg-layer-2)',
      },
    },
    React.createElement(
      'div',
      {
        className: 'cb-progress-head cb-bar-head',
        style: {
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'baseline',
          gap: '16px',
          width: '100%',
        },
      },
      React.createElement(
        'span',
        { className: 'cb-progress-label', style: { fontWeight: 500, whiteSpace: 'nowrap' } },
        label,
        isBad
          ? React.createElement(
              'span',
              { style: { display: 'inline-flex', alignItems: 'center', gap: '4px', marginLeft: '6px', fontSize: '11px', color: 'var(--dsw-alias-state-error-primary)' } },
              React.createElement(CbIcon, { name: 'warning', size: 12 }),
              '<10%'
            )
          : null
      ),
      React.createElement(
        'span',
        {
          className: 'cb-progress-meta cb-bar-meta',
          style: {
            fontSize: '12px',
            color: isBad ? 'var(--dsw-alias-state-error-primary)' : 'var(--dsw-alias-label-secondary)',
            whiteSpace: 'nowrap',
            marginLeft: 'auto',
          },
        },
        t('quota.used', { pct }),
        resetCountdown ? ` · ${resetCountdown === 'resetting' ? (t('quota.resetting') || '正在重置') : t('quota.countdown', { time: resetCountdown })}` : (resetClock ? ` · ${t('quota.reset_at', { time: resetClock })}` : '')
      )
    ),
    React.createElement(
      'div',
      {
        className: 'cb-progress-track cb-bar-track',
        style: {
          width: '100%',
          height: '8px',
          borderRadius: '999px',
          background: 'var(--dsw-alias-bg-layer-1)',
          overflow: 'hidden',
          border: '1px solid var(--dsw-alias-border-l2)',
        },
      },
      React.createElement('div', {
        className: barClass,
        style: { width: `${pct}%`, height: '100%', borderRadius: '999px' },
      })
    )
  )
}

